			/*updateMasterWmGiDstbtrICOMPORS_GiOrder*/
			UPDATE ICOMPORS
     			  SET BUYER_DS_DATE = NVL(#{SCHEDULED_DATE},F_GET_WORKINGDAY(to_char(sysdate,'YYYYMMDD'),1))
     			     ,CHANGE_DATE = TO_CHAR(SYSDATE, 'YYYYMMDD')
					 ,CHANGE_TIME = TO_CHAR(SYSDATE, 'HH24MISS')
              	WHERE BUYER   = #{BUYER}                              
                  AND PO_NO   = #{PO_NO}
                  AND PO_SEQ  = #{PO_SEQ}
                  AND STATUS != 'D'
